#!/usr/bin/env node
/*
  Checks a stitched story on the locally running site. It opens
  a page with a story (/preview by default, with a mix, person and look if
  given), stops at the middle of every chapter's hold and at two points of
  every move, saves a screenshot of each, and
  fails on a page error, a failed request or a blank picture.

    node scripts/stitch-check.mjs --url http://127.0.0.1:3000 \
      --mix sheet,map,book,book,sheet,sheet,map,map [--person noa] [--look daylight] \
      [--size 1440x900] [--out checks/stitch] [--points] [--words]

  Options
    --url=URL       the site's address (required)
    --path=PATH     the page to open, default /preview; / is the person's site
    --mix=TEXT      eight world ids in chapter order; default the page's own
    --person=KEY    a sample person, noa or amara; default the site's own
    --look=ID       a look, night, daylight or blueprint; default the page's own
    --size=WxH      viewport, default 1440x900
    --out=DIR       where report.json and the PNGs go, default checks/stitch
    --points        also shoot the first move between two worlds at raw
                    0.1, 0.5, 0.9 and 1.0, to see the dive end where the
                    next world begins
    --at=LIST       also shoot at these points, in chapters from the top
                    (2.2 is the middle of the third chapter's hold)
    --words         keep the words on screen; by default they are hidden,
                    so a shot shows only the picture
    --wait=MS       settle time after each scroll, default 500

  Shots are taken with reduced motion, so the story stands exactly where
  the page is scrolled. A shot is blank when fewer than 0.5 per cent of
  sampled pixels of the 3D differ clearly from its corner pixel. A failed
  draw is near 0; the map's dim ground does not count, so a phone's view of
  places far apart can be under 1 per cent and still drawn.

  Chromium comes from playwright-core (npm run browsers). CHROMIUM names
  another Chromium to start instead.
*/
import { mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";

const options = Object.fromEntries(process.argv.slice(2).map((arg, i, all) => {
  const m = /^--([^=]+)(?:=(.*))?$/.exec(arg);
  if (!m) return [];
  if (m[2] !== undefined) return [m[1], m[2]];
  const next = all[i + 1];
  return [m[1], next && !next.startsWith("--") ? next : true];
}).filter((x) => x.length));

function usage(message) {
  console.error(`${message}\nSee the comment at the top of scripts/stitch-check.mjs.`);
  process.exit(2);
}
if (!options.url) usage("--url is required.");
const [width, height] = String(options.size ?? "1440x900").split("x").map(Number);
if (![width, height].every((n) => Number.isFinite(n) && n > 0)) usage("--size must be positive WxH");
const out = path.resolve(String(options.out ?? "checks/stitch"));
mkdirSync(out, { recursive: true });
const settle = Number(options.wait ?? 500);

const { chromium } = createRequire(import.meta.url)("playwright-core");
const browser = await chromium.launch({
  ...(process.env.CHROMIUM ? { executablePath: process.env.CHROMIUM } : {}),
  args: ["--no-sandbox", "--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist"],
});
const context = await browser.newContext({ viewport: { width, height }, deviceScaleFactor: 1, reducedMotion: "reduce" });
const page = await context.newPage();
const problems = [];
page.on("pageerror", (e) => problems.push(`page error: ${e.message}`));
// A failed resource is reported with its address by the response handler below;
// the console line for it (and for the browser's own favicon request) adds nothing.
page.on("console", (m) => { if (m.type() === "error" && !m.text().startsWith("Failed to load resource")) problems.push(`console error: ${m.text()}`); });
page.on("requestfailed", (r) => problems.push(`request failed: ${r.url()} ${r.failure()?.errorText ?? ""}`));
page.on("response", (r) => { if (r.status() >= 400) problems.push(`HTTP ${r.status()}: ${r.url()}`); });

const query = new URLSearchParams();
if (options.mix && options.mix !== true) query.set("mix", String(options.mix));
if (options.person && options.person !== true) query.set("person", String(options.person));
if (options.look && options.look !== true) query.set("look", String(options.look));
const where = `/${String(options.path && options.path !== true ? options.path : "/preview").replace(/^\/+/, "")}`;
const address = `${String(options.url).replace(/\/$/, "")}${where}${query.size ? `?${query}` : ""}`;
const report = { address, size: `${width}x${height}`, shots: [], problems };

async function finish(code) {
  writeFileSync(path.join(out, "report.json"), JSON.stringify(report, null, 2));
  await browser.close();
  for (const p of problems) console.error(p);
  console.log(`${report.shots.length} shots, ${problems.length} problems: ${out}`);
  process.exit(code);
}

const response = await page.goto(address, { waitUntil: "load" });
if (!response || !response.ok()) { problems.push(`could not open ${address}: ${response?.status()}`); await finish(1); }
try {
  await page.waitForFunction(() => window.__stitch?.ready || window.__stitch?.error, null, { timeout: 60000 });
} catch { problems.push("the story never said it was ready"); await finish(1); }
const error = await page.evaluate(() => window.__stitch.error ?? null);
if (error) { problems.push(`the story failed: ${error}`); await finish(1); }
if (!options.words) await page.evaluate(() => document.querySelector(".stitch")?.classList.add("nowords"));
const { keys, mix: shown } = await page.evaluate(() => ({ keys: window.__stitch.keys, mix: window.__stitch.mix }));

async function shoot(name, at) {
  await page.evaluate((s) => window.scrollTo({ top: window.__stitch.top() + s * window.__stitch.unit(), behavior: "instant" }), at);
  await page.waitForTimeout(settle);
  await page.evaluate(() => new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r))));
  const sample = await page.evaluate(() => window.__stitch.sample());
  const file = `${name}.png`;
  await page.screenshot({ path: path.join(out, file) });
  const state = await page.evaluate(() => window.__stitch.state());
  report.shots.push({ name, at, file, drawn: sample, state });
  if (sample < 0.005) problems.push(`${name} is blank (${(sample * 100).toFixed(2)} per cent drawn)`);
}

for (let k = 0; k < keys.length; k++) {
  const num = String(k + 1).padStart(2, "0");
  await shoot(`${num}-${keys[k]}-hold`, k + 0.2);
  if (k + 1 < keys.length) await shoot(`${num}-${keys[k]}-move`, k + 0.7);
}
if (options.points) {
  const mix = shown.split(",");
  const order = ["hello", "from", "studied", "worked", "good", "made", "say", "contact"];
  const k = keys.findIndex((key, i) => i + 1 < keys.length && mix[order.indexOf(key)] !== mix[order.indexOf(keys[i + 1])]);
  if (k < 0) problems.push("--points: this mix has no move between two worlds");
  else for (const raw of [0.1, 0.5, 0.9, 1.0]) await shoot(`dive-${keys[k]}-raw-${raw.toFixed(1)}`, k + 0.4 + 0.6 * raw - (raw === 1 ? 1e-4 : 0));
}
if (options.at && options.at !== true) {
  for (const at of String(options.at).split(",").map(Number).filter(Number.isFinite)) await shoot(`at-${at.toFixed(2)}`, at);
}
await finish(problems.length ? 1 : 0);
/** A small drawing that stands for a project, by its kind. */
export function miniPicture(ctx: CanvasRenderingContext2D, C: Palette, kind: string, x: number, y: number, w: number, h: number, seed = 1) {
  ctx.save();
  ctx.beginPath(); ctx.rect(x, y, w, h); ctx.clip();
  ctx.fillStyle = "#e8e2d4"; ctx.fillRect(x, y, w, h);
  const rnd = (i: number) => rand(seed, i);
  ctx.lineWidth = Math.max(2, w / 90);
  if (kind === "chart") {
    ctx.strokeStyle = "#c9c1b0";
    for (let i = 1; i < 4; i++) { ctx.beginPath(); ctx.moveTo(x, y + (h * i) / 4); ctx.lineTo(x + w, y + (h * i) / 4); ctx.stroke(); }
    ctx.strokeStyle = C.ink; ctx.beginPath();
    for (let i = 0; i <= 24; i++) { const px = x + (w * i) / 24, py = y + h * (0.65 - 0.3 * Math.sin(i / 3.5) * (0.6 + 0.4 * rnd(i))); if (i) ctx.lineTo(px, py); else ctx.moveTo(px, py); }
    ctx.stroke();
    ctx.strokeStyle = C.amber; ctx.setLineDash([w / 40, w / 60]); ctx.beginPath();
    for (let i = 16; i <= 24; i++) { const px = x + (w * i) / 24, py = y + h * (0.6 - 0.25 * Math.sin(i / 3.5)); if (i === 16) ctx.moveTo(px, py); else ctx.lineTo(px, py); }
    ctx.stroke(); ctx.setLineDash([]);
  } else if (kind === "photo") {
    const g = ctx.createLinearGradient(x, y, x, y + h);
    g.addColorStop(0, "#9cc3d9"); g.addColorStop(0.6, "#e8d4a8"); g.addColorStop(1, "#8a9a6a");
    ctx.fillStyle = g; ctx.fillRect(x, y, w, h);
    ctx.fillStyle = "#c46a4a"; ctx.fillRect(x + w * 0.15, y + h * 0.35, w * 0.25, h * 0.45);
    ctx.fillStyle = "#5d7f9a"; ctx.fillRect(x + w * 0.5, y + h * 0.25, w * 0.3, h * 0.55);
    ctx.fillStyle = "rgba(120,120,120,0.92)"; ctx.fillRect(x, y, w / 2, h);
    ctx.fillStyle = "#7a7a7a"; ctx.fillRect(x + w * 0.15, y + h * 0.35, w * 0.25, h * 0.45);
    ctx.strokeStyle = "#fff"; ctx.beginPath(); ctx.moveTo(x + w / 2, y); ctx.lineTo(x + w / 2, y + h); ctx.stroke();
  } else if (kind === "maze") {
    const n = 7, cw = w / n, ch = h / n;
    ctx.strokeStyle = C.ink;
    for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
      ctx.beginPath();
      if (rnd(i * 7 + j) > 0.5) { ctx.moveTo(x + i * cw, y + j * ch); ctx.lineTo(x + (i + 1) * cw, y + j * ch); }
      else { ctx.moveTo(x + i * cw, y + j * ch); ctx.lineTo(x + i * cw, y + (j + 1) * ch); }
      ctx.stroke();
    }
    ctx.strokeStyle = C.amber; ctx.lineWidth *= 1.6; ctx.beginPath();
    ctx.moveTo(x + cw / 2, y + ch / 2); ctx.lineTo(x + cw / 2, y + ch * 3.5); ctx.lineTo(x + cw * 3.5, y + ch * 3.5); ctx.lineTo(x + cw * 3.5, y + ch * 6.5); ctx.lineTo(x + cw * 6.5, y + ch * 6.5);
    ctx.stroke();
  } else if (kind === "route") {
    ctx.strokeStyle = "#d3cbb9";
    for (let i = 0; i < 9; i++) { ctx.beginPath(); ctx.moveTo(x, y + rnd(i) * h); ctx.lineTo(x + w, y + rnd(i + 20) * h); ctx.stroke(); }
    ctx.strokeStyle = C.teal; ctx.lineWidth *= 2; ctx.beginPath();
    ctx.moveTo(x + w * 0.1, y + h * 0.85);
    ctx.bezierCurveTo(x + w * 0.4, y + h * 0.9, x + w * 0.3, y + h * 0.3, x + w * 0.88, y + h * 0.18);
    ctx.stroke();
    ctx.fillStyle = C.rose; ctx.beginPath(); ctx.arc(x + w * 0.88, y + h * 0.18, w / 30, 0, Math.PI * 2); ctx.fill();
  } else if (kind === "bars") {
    for (let i = 0; i < 14; i++) {
      const bh = h * (0.15 + 0.35 * rnd(i)) * (i === 9 ? 1.9 : 1);
      ctx.fillStyle = i === 9 ? C.rose : "#9aa3ab";
      ctx.fillRect(x + (w * (i + 0.15)) / 14, y + h - bh - h * 0.08, (w / 14) * 0.7, bh);
    }
  } else {
    ctx.font = sans(h / 9);
    for (let i = 0; i < 5; i++) {
      const ly = y + h * (0.16 + i * 0.17);
      ctx.strokeStyle = C.ink; ctx.strokeRect(x + w * 0.1, ly, h / 12, h / 12);
      if (i < 2) { ctx.fillStyle = C.teal; ctx.fillRect(x + w * 0.1 + 3, ly + 3, h / 12 - 6, h / 12 - 6); }
      ctx.fillStyle = "#a59e90"; ctx.fillRect(x + w * 0.25, ly + h / 40, w * (0.35 + 0.3 * rnd(i)), h / 30);
    }
  }
  ctx.restore();
}

/** Paper's fleck, the same for the same seed so a picture does not change between visits. */
export function grain(ctx: CanvasRenderingContext2D, w: number, h: number, n = 9000, seed = 7) {
  for (let i = 0; i < n; i++) {
    ctx.fillStyle = rand(seed, i * 3) < 0.5 ? "rgba(90,70,40,0.05)" : "rgba(255,255,255,0.06)";
    ctx.fillRect(rand(seed, i * 3 + 1) * w, rand(seed, i * 3 + 2) * h, 2, 2);
  }
}

export type DieCut = HTMLCanvasElement & { edge: number };

  canvas(w, h, (ctx) => { draw(ctx, w, h); grain(ctx, w, h, Math.round((w * h) / 150), w + h); });

function cvPage(P: Person, C: Palette) {
  return printed(1024, 1448, (ctx, w) => {
    ctx.fillStyle = C.paper; ctx.fillRect(0, 0, w, 1448);
    const m = 84;
    ctx.fillStyle = C.ink; ctx.font = serif(80); ctx.fillText(P.name, m, 170);
    ctx.fillStyle = C.amber; ctx.font = sans(30, 600); ctx.fillText(P.role.toUpperCase(), m, 225);
    ctx.fillStyle = C.ink; ctx.font = serif(32, 400, "italic"); wrap(ctx, P.line, m, 285, w - 2 * m, 42, 2);
    ctx.fillStyle = C.line; ctx.fillRect(m, 345, w - 2 * m, 3);
    const sec = (y: number, head: string, rows: string[]) => {
      if (!rows.length) return y;
      ctx.fillStyle = C.amber; ctx.font = sans(20, 600); ctx.fillText(head.toUpperCase(), m, y);
      ctx.fillStyle = C.ink; ctx.font = sans(24);
      let yy = y;
      for (const row of rows) { yy = wrap(ctx, row, m + 230, yy, w - 2 * m - 230, 32, 3); yy += 4; }
      return Math.max(yy, y + 34) + 26;
    };
    let y = 410;
    y = sec(y, "Places", P.places.length ? [P.places.map((p) => p.name).join("  >  ")] : []);
    y = sec(y, "Education", P.study.map((s) => `${s.degree}, ${s.field}. ${s.place}, ${s.from} to ${s.to}`));
    y = sec(y, "Experience", P.work.slice(0, 5).map((x) => `${x.role}, ${x.org}, ${x.place}. ${yearText(x)}`));
    y = sec(y, "Skills", P.skills.slice(0, 5).map((g) => `${g.group}: ${g.items.join(", ")}`));
    y = sec(y, "Projects", P.projects.length ? [P.projects.map((p) => p.title).join(", ")] : []);
    y = sec(y, "References", P.quotes.slice(0, 4).map((q) => `${q.who}, ${q.from}`));
    sec(y, "Contact", [P.contact.email]);
  });
}

function globeMap(land: Land, C: Palette) {
  return printed(2048, 1024, (ctx, w, h) => {
    ctx.fillStyle = C.paper; ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = "rgba(28,34,42,0.10)"; ctx.lineWidth = 2;
    for (let lng = -180; lng <= 180; lng += 15) { const [x] = equirect(lng, 0, w, h); ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke(); }
    for (let lat = -75; lat <= 75; lat += 15) { const [, y] = equirect(0, lat, w, h); ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke(); }
    const stretch = (y: number) => Math.min(5, 1 / Math.max(0.05, Math.cos(((90 - (y / h) * 180) * Math.PI) / 180)));
    dotLand(ctx, land, (lng, lat) => equirect(lng, lat, w, h), w, h, 7, 2.3, "rgba(28,34,42,0.78)", stretch);
  });
}

function diplomaPicture(P: Person, C: Palette) {
  const s = P.study[0];
  return printed(1500, 1000, (ctx, w, h) => {
    ctx.fillStyle = C.paper; ctx.fillRect(0, 0, w, h);
    const m = w * ROLL + 40;
    ctx.strokeStyle = C.amber; ctx.lineWidth = 6; ctx.strokeRect(m, 50, w - 2 * m, h - 100);
    ctx.lineWidth = 2; ctx.strokeRect(m + 16, 66, w - 2 * m - 32, h - 132);
    ctx.textAlign = "center"; const cx = w / 2;
    ctx.fillStyle = C.muted; ctx.font = sans(26, 600); ctx.fillText(`${s.place.toUpperCase()}  ·  ${s.from} TO ${s.to}`, cx, 170);
    ctx.fillStyle = C.ink; ctx.font = serif(36, 400, "italic"); ctx.fillText("This certifies that", cx, 260);
    ctx.font = serif(84); ctx.fillText(P.name, cx, 360);
    ctx.font = serif(32, 400, "italic"); ctx.fillText("has been awarded the degree of", cx, 440);
    ctx.font = serif(60); ctx.fillText(s.degree, cx, 530);
    ctx.font = serif(44, 400); ctx.fillText(`in ${s.field}`, cx, 595);
    if (s.note) { ctx.fillStyle = C.muted; ctx.font = sans(26); ctx.fillText(s.note, cx, 690); }
    if (P.study.length > 1) { ctx.fillStyle = C.muted; ctx.font = sans(24); ctx.fillText(`and ${P.study.length - 1} more`, cx, 735); }
    ctx.fillStyle = C.amber; ctx.beginPath(); ctx.arc(cx, 820, 62, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = C.paper; ctx.font = sans(24, 600); ctx.fillText(String(s.to), cx, 830);
  });
}

function timeline(P: Person, C: Palette) {
  const [y0, y1] = yearRange(P);
  return printed(4096, 532, (ctx, w, h) => {
    ctx.fillStyle = C.paper; ctx.fillRect(0, 0, w, h);
    const X = (yr: number) => 120 + ((yr - y0) / (y1 - y0)) * (w - 240), axis = 400;
    ctx.fillStyle = C.ink; ctx.fillRect(100, axis, w - 200, 4);
    ctx.font = sans(30, 600); ctx.textAlign = "center";
    const every = Math.ceil((y1 - y0) / 16);
    for (let yr = y0; yr <= y1; yr += every) { ctx.fillRect(X(yr) - 2, axis - 10, 4, 24); ctx.fillText(String(yr), X(yr), axis + 60); }
    ctx.textAlign = "left";
    const bar = (a: number, b: number, row: number, color: string, head: string, sub: string) => {
      const y = 120 + row * 110;
      ctx.fillStyle = color; rrect(ctx, X(a), y + 52, Math.max(30, X(b) - X(a)), 26, 13); ctx.fill();
      ctx.fillStyle = C.ink; ctx.font = serif(40); ctx.fillText(head, X(a), y + 30);
      ctx.fillStyle = C.muted; ctx.font = sans(26); ctx.fillText(sub, X(a), y + 112);
      ctx.strokeStyle = color; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(X(a), y + 78); ctx.lineTo(X(a), axis); ctx.stroke();
    };
    for (const s of P.study) bar(s.from, s.to, 0, "rgba(63,167,150,0.55)", `Studied in ${s.place}`, s.field);
    P.work.forEach((x, i) => bar(x.from, x.to ?? NOW, (i + 1) % 2, i === P.work.length - 1 ? C.amber : C.ink, x.org, `${x.role}, ${x.place}. ${yearText(x)}`));
  });
}

function leafletPicture(P: Person, C: Palette) {
  return printed(2048, 1024, (ctx, w, h) => {
    const pw = w / 4;
    const { shown, more } = slots(P.skills, 4);
    shown.forEach((g, i) => {
      const x = i * pw;
      ctx.fillStyle = i % 2 ? C.paperDark : C.paper; ctx.fillRect(x, 0, pw, h);
      if (!g) return;
      ctx.fillStyle = C.amber; ctx.font = sans(26, 600); ctx.fillText(String(i + 1).padStart(2, "0"), x + 48, 110);
      ctx.fillStyle = C.ink; ctx.font = serif(54); wrap(ctx, g.group, x + 48, 190, pw - 90, 60, 2);
      ctx.font = sans(38);
      const items = slots(g.items, 5);
      items.shown.forEach((it, j) => {
        if (!it) return;
        const y = 360 + j * 112;
        ctx.fillStyle = C.ink; rrect(ctx, x + 44, y - 50, pw - 88, 76, 38); ctx.lineWidth = 3; ctx.strokeStyle = C.ink; ctx.stroke();
        ctx.fillText(it, x + 74, y);
      });
      const extra = items.more + (i === 3 ? more : 0);
      if (extra) { ctx.fillStyle = C.muted; ctx.font = sans(30, 600); ctx.fillText(`and ${extra} more`, x + 48, h - 50); }
    });
  });
}

function wallPicture(P: Person, C: Palette) {
  return printed(2048, 1024, (ctx, w, h) => {
    const cw = w / 3, ch = h / 2;
    const { shown, more } = slots(P.projects, 6);
    shown.forEach((p, i) => {
      const x = (i % 3) * cw, y = Math.floor(i / 3) * ch;
      ctx.fillStyle = C.paper; ctx.fillRect(x, y, cw, ch);
      if (!p) return;
      miniPicture(ctx, C, p.kind, x + 28, y + 28, cw - 56, ch * 0.5, i + 3);
      ctx.fillStyle = C.ink; ctx.font = serif(40); ctx.fillText(p.title, x + 30, y + ch * 0.5 + 92);
      ctx.fillStyle = C.muted; ctx.font = sans(24); wrap(ctx, p.line, x + 30, y + ch * 0.5 + 134, cw - 60, 30, 2);
      ctx.fillStyle = C.amber; ctx.font = sans(22, 600); ctx.fillText(`${p.place.toUpperCase()}  ${p.year}`, x + 30, y + ch - 30);
      if (i === 5 && more) { ctx.fillStyle = C.ink; ctx.textAlign = "right"; ctx.fillText(`AND ${more} MORE`, x + cw - 30, y + ch - 30); ctx.textAlign = "left"; }
    });
  });
}

function quotePicture(P: Person, C: Palette) {
  return printed(2048, 1448, (ctx, w, h) => {
    const cw = w / 3;
    const { shown, more } = slots(P.quotes, 3);
    shown.forEach((q, i) => {
      const x = i * cw;
      ctx.fillStyle = C.paper; ctx.fillRect(x, 0, cw, h);
      if (!q) return;
      ctx.fillStyle = C.amber; ctx.font = serif(220); ctx.fillText("“", x + 40, 250);
      ctx.fillStyle = C.ink; ctx.font = serif(46, 400, "italic");
      const y = wrap(ctx, q.text, x + 56, 330, cw - 112, 62, 11);
      ctx.fillStyle = C.ink; ctx.font = sans(32, 600); ctx.fillText(q.who, x + 56, Math.max(y + 60, h - 220));
      ctx.fillStyle = C.muted; ctx.font = sans(26); wrap(ctx, q.from, x + 56, Math.max(y + 104, h - 176), cw - 112, 32, 2);
      if (i === 2 && more) { ctx.fillStyle = C.amber; ctx.font = sans(26, 600); ctx.fillText(`AND ${more} MORE`, x + 56, h - 70); }
    });
  });
}

function contactPage(P: Person, C: Palette, whole: boolean) {
  return printed(1024, 1448, (ctx, w, h) => {
    ctx.fillStyle = C.paper; ctx.fillRect(0, 0, w, h);
    const m = 84;
    ctx.fillStyle = C.amber; ctx.font = sans(26, 600); ctx.fillText("GET IN TOUCH", m, 200);
    ctx.fillStyle = C.ink; ctx.font = serif(86); wrap(ctx, `Write to ${P.first}`, m, 310, w - 2 * m, 96, 2);
    ctx.font = serif(46, 400); ctx.fillText(P.contact.email, m, 470);
    ctx.fillStyle = C.muted; ctx.font = sans(30); wrap(ctx, `${P.seeking}.`, m, 540, w - 2 * m, 40, 2);
    ctx.fillStyle = C.line; ctx.fillRect(m, 620, w - 2 * m, 3);
    ctx.fillStyle = C.ink; ctx.font = sans(34, 600);
    P.contact.links.slice(0, 6).forEach((l, i) => ctx.fillText(`${l}  →`, m, 710 + i * 70));
    ctx.fillStyle = C.muted; ctx.font = serif(30, 400, "italic");
    // Only a story told wholly on the sheet folded into every picture.
    wrap(ctx, `This sheet is ${P.first}'s CV.${whole ? " It folded into every picture above." : ""}`, m, h - 200, w - 2 * m, 42);
  });
}

const PICTURES: Record<ChapterKey, (P: Person, land: Land, C: Palette, whole: boolean) => HTMLCanvasElement> = {
  hello: (P, land, C) => cvPage(P, C), from: (P, land, C) => globeMap(land, C), studied: (P, land, C) => diplomaPicture(P, C),
  worked: (P, land, C) => timeline(P, C), good: (P, land, C) => leafletPicture(P, C), made: (P, land, C) => wallPicture(P, C),
  say: (P, land, C) => quotePicture(P, C), contact: (P, land, C, whole) => contactPage(P, C, whole),
};

// ---------- The sheet ----------

// The words a book page carries for one chapter. Pure.
import { yearText, type ChapterKey } from "./chapters.ts";
import { slots, type Person, type Project } from "./person.ts";

/** The words of one chapter as lines for a page: the person's chosen words when they chose some, else written from their data. */
export function pageLines(P: Person, k: ChapterKey, chosen?: string): string[] {
  const own = chosen?.trim();
  if (own) return [own];
  const more = (n: number) => (n ? [`And ${n} more.`] : []);
  switch (k) {
    case "hello": return [P.name, P.role, P.line, P.seeking + "."];
    case "from": return P.places.slice(0, 6).map((p) => `${p.name}, where ${P.first} ${p.what}.`).concat(more(Math.max(0, P.places.length - 6)));
    case "studied": return P.study.slice(0, 2).flatMap((s) => [`${s.degree} in ${s.field}.`, `${s.place}, ${s.from} to ${s.to}.`, ...(s.note ? [s.note + "."] : [])]).concat(more(Math.max(0, P.study.length - 2)));
    case "worked": return P.work.slice(0, 5).map((w) => `${w.org}, ${w.place}, ${yearText(w)}. ${w.role}: ${w.did.charAt(0).toLowerCase()}${w.did.slice(1)}.`).concat(more(Math.max(0, P.work.length - 5)));
    case "good": return P.skills.slice(0, 6).map((g) => `${g.group}: ${g.items.join(", ")}.`).concat(more(Math.max(0, P.skills.length - 6)));
    case "made": {
      const s = slots(P.projects, 6);
      return [`${P.projects.length} ${P.projects.length === 1 ? "project" : "projects"}. Open any card on the right to read about it.`,
        ...s.shown.filter((p): p is Project => !!p).map((p) => p.title), ...more(s.more)];
    }
    case "say": {
      const s = slots(P.quotes, 3);
      return [...s.shown.filter((q) => !!q).map((q) => `${q!.who}, ${q!.from}.`), ...more(s.more)];
    }
    case "contact": return [P.contact.email, P.seeking + ".", P.contact.links.join(", ") + "."];
  }
}
"use client";
// A stitched story on a page: the 3D behind, the chapter's words, the
// chapter rail, the contact buttons and a project window. The words are
// also written out in full for anyone without the 3D.
import { useEffect, useMemo, useRef, useState, type CSSProperties } from "react";
import { titleOf, wordsFor, type ChapterKey } from "./chapters.ts";
import { chaptersFor, type Person, type Project } from "./person.ts";
import { formatMix, parseMix, type Mix } from "./mix.ts";
import { LOOKS, uiColours, type LookId, type Palette } from "./look.ts";
import { miniPicture, canvas as paintCanvas } from "./paint.ts";
import { smooth, type ScrollState } from "./scroll.ts";
import "./stitch.css";

type Handle = { dispose(): void; goTo(index: number, instant?: boolean): void };

/** The custom properties stitch.css colours the words, rail, caption and buttons with. */
function lookStyle(p: Palette): CSSProperties {
  const ui = uiColours(p);
  return { "--st-bg": p.bg, "--st-ink": ui.text, "--st-soft": ui.soft, "--st-muted": ui.muted, "--st-glass": ui.glass,
    "--st-line": ui.line, "--st-on-ink": ui.onText, "--st-amber": p.amber } as CSSProperties;
}

/**
 * `start` opens the story at that chapter when the page is at its top, as a link to one chapter's piece does.
 * `words` are the person's own words for any chapter; `cv` is where their CV is, and its button shows only with it.
 */
export function StitchedStory({ person, mix, showWords = true, start, look = "night", words: chosen, cv }: {
  person: Person; mix: Mix; showWords?: boolean; start?: ChapterKey; look?: LookId; words?: Partial<Record<ChapterKey, string>>; cv?: string;
}) {
  const palette = LOOKS[look];
  const keys = useMemo(() => chaptersFor(person), [person]);
  const words = useMemo(() => wordsFor(person, keys, chosen), [person, keys, chosen]);
  const mixText = formatMix(mix);
  const chosenText = JSON.stringify(chosen ?? {});
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const spacerRef = useRef<HTMLDivElement>(null);
  const capRef = useRef<HTMLDivElement>(null);
  const hintRef = useRef<HTMLDivElement>(null);
  const ctaRef = useRef<HTMLDivElement>(null);
  const handle = useRef<Handle | null>(null);
  const nearRef = useRef(0);
  const [near, setNear] = useState(0);
  const [scene, setScene] = useState<"wait" | "on" | "off">("wait");
  const [project, setProject] = useState<Project | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current, spacer = spacerRef.current;
    if (!canvas || !spacer) return;
    let alive = true;
    const last = keys.length - 1;
    const onState = (st: ScrollState) => {
      const n = st.t < 0.5 ? st.from : st.to;
      if (n !== nearRef.current) { nearRef.current = n; setNear(n); }
      const fade = st.to === st.from ? 1 : 1 - smooth(0.05, 0.35, st.raw) + smooth(0.65, 0.95, st.raw);
      if (capRef.current) capRef.current.style.opacity = fade.toFixed(3);
      if (hintRef.current) hintRef.current.style.opacity = st.s < 0.15 ? "1" : "0";
      const cta = st.from === last ? 1 : st.to === last ? smooth(0.7, 1, st.raw) : 0;
      if (ctaRef.current) { ctaRef.current.style.opacity = cta.toFixed(3); ctaRef.current.style.pointerEvents = cta > 0.5 ? "auto" : "none"; }
    };
    import("./stage.ts")
      .then(({ mountStitch }) => mountStitch(canvas, { person, mix: parseMix(mixText)!, palette: LOOKS[look], words: JSON.parse(chosenText), spacer, onState, onProject: setProject }))
      .then((h) => {
        if (!alive) { h.dispose(); return; }
        handle.current = h;
        setScene("on");
        const at = start ? keys.indexOf(start) : -1;
        if (at > 0 && window.scrollY < 2) h.goTo(at, true);
      })
      .catch((e) => { console.error(e); if (alive) setScene("off"); });
    return () => { alive = false; handle.current?.dispose(); handle.current = null; };
  }, [person, mixText, keys, start, look, chosenText]);

  useEffect(() => {
    if (!project) return;
    const close = (e: KeyboardEvent) => { if (e.key === "Escape") setProject(null); };
    window.addEventListener("keydown", close);
    return () => window.removeEventListener("keydown", close);
  }, [project]);

  const key = keys[near];
  return (
    <div className={`stitch${showWords ? "" : " nowords"}`} data-scene={scene} style={lookStyle(palette)}>
      <canvas ref={canvasRef} className="gl" aria-hidden="true" />
      <div ref={spacerRef} className="spacer" />
      <div className="ui">
        <nav className="rail" aria-label="Chapters">
          {keys.map((k, i) => (
            <button key={k} type="button" className={i === near ? "on" : ""} onClick={() => handle.current?.goTo(i)}>
              <i /><span>{titleOf(k)}</span>
            </button>
          ))}
        </nav>
        <div ref={capRef} className={`cap${mix[key] === "book" ? " inbook" : ""}`} aria-live="polite">
          <div className="num">{String(near + 1).padStart(2, "0")}</div>
          <h2>{titleOf(key)}</h2>
          <p>{words[key]}</p>
        </div>
        <div ref={hintRef} className="hint">Scroll</div>
      </div>
      <div ref={ctaRef} className="cta">
        <a href={`mailto:${person.contact.email}`}>Email {person.first}</a>
        {cv && <a href={cv}>CV</a>}
      </div>
      <Chapters person={person} keys={keys} words={words} cv={cv} />
      <Expected person={person} words={words} cv={cv} />
      {project && <ProjectWindow project={project} palette={palette} onClose={() => setProject(null)} />}
    </div>
  );
}

/** Every chapter's words in order, shown when there is no 3D and read by screen readers. */
function Chapters({ person, keys, words, cv }: { person: Person; keys: ChapterKey[]; words: Partial<Record<ChapterKey, string>>; cv?: string }) {
  return (
    <section className="text" aria-label={`${person.name}, in words`}>
      <h1>{person.name}</h1>
      {keys.map((k) => (
        <article key={k}>
          <h2>{titleOf(k)}</h2>
          <p>{words[k]}</p>
          {k === "made" && <ul>{person.projects.map((p) => <li key={p.title}><b>{p.page ? <a href={p.page}>{p.title}</a> : p.title}</b>. {p.line}{p.more && <> {p.more}</>}</li>)}</ul>}
          {k === "say" && <ul>{person.quotes.map((q) => <li key={q.who}>&ldquo;{q.text}&rdquo; {q.who}, {q.from}</li>)}</ul>}
          {k === "contact" && <p><a href={`mailto:${person.contact.email}`}>{person.contact.email}</a>{cv && <>. <a href={cv}>CV</a></>}</p>}
        </article>
      ))}
    </section>
  );
}

/** What the page must show without its 3D, as JSON for scripts/site-check.mjs to look for. */
function Expected({ person, words, cv }: { person: Person; words: Partial<Record<ChapterKey, string>>; cv?: string }) {
  const wanted = {
    name: person.name,
    words: Object.values(words),
    projects: person.projects.map(({ title, line, more, page }) => ({ title, line, more, page })),
    cv,
  };
  return <script type="application/json" data-stitch-expect dangerouslySetInnerHTML={{ __html: JSON.stringify(wanted).replace(/</g, "\\u003c") }} />;
}

function ProjectWindow({ project, palette, onClose }: { project: Project; palette: Palette; onClose: () => void }) {
  const pic = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const el = pic.current;
    if (!el) return;
    const c = paintCanvas(800, 420, (ctx, w, h) => miniPicture(ctx, palette, project.kind, 0, 0, w, h, project.title.length));
    el.replaceChildren(c);
  }, [project, palette]);
  return (
    <div className="modal open" role="dialog" aria-modal="true" aria-label={project.title} onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="sheet">
        <button type="button" data-close aria-label="Close" onClick={onClose}>&times;</button>
        <div className="pic" ref={pic} />
        <div className="body">
          <div className="eyebrow">{project.place}, {project.year}</div>
          <h3>{project.title}</h3>
          <p>{project.line}</p>
          {project.more && <p>{project.more}</p>}
          {project.page && <p><a className="more" href={project.page}>More about {project.title}</a></p>}
          <div className="tags">{project.tags.map((t) => <span key={t}>{t}</span>)}</div>
        </div>
      </div>
    </div>
  );
}

